test('new empty counters and atomic concurrent same receipt only count once',async()=>{const{db,r}=await setup();assert.deepEqual(await r.totals(),{'pole-vault':{count:0,since:null},'shot-put':{count:0,since:null},discus:{count:0,since:null},'sprint-100m':{count:0,since:null},'run-400m':{count:0,since:null},'run-1500m':{count:0,since:null},javelin:{count:0,since:null},'beer-slide':{count:0,since:null},'tower-climb':{count:0,since:null},'courtesy-contest':{count:0,since:null},taiwanfighter:{count:0,since:null},taiwankart:{count:0,since:null},soul10power:{count:0,since:null},arcadeplatform:{count:0,since:null},'high-jump':{count:0,since:null},'long-jump':{count:0,since:null},hurdles:{count:0,since:null},'reaction-rod':{count:0,since:null},'fast-hands':{count:0,since:null},'fast-hands-catch':{count:0,since:null},'fast-hands-duel':{count:0,since:null},home:{count:0,since:null}});const results=await Promise.all([r.start(base,now),r.start(base,now)]);assert.equal(results.filter(x=>x.duplicate).length,1);assert.equal((await r.totals()).hurdles.count,1);assert.equal((await r.totals()).hurdles.since,now);assert.equal((await r.start({...base,game:'long-jump'},now)).error,'conflict');assert.equal(db.raw.exec('SELECT count(*) FROM leaderboard_best')[0].values[0][0],0);});
test('cooldown refuses new id, subsequent genuine attempt increments, cleanup never increments twice',async()=>{const{db,r}=await setup();await r.start(base,now);assert.equal((await r.start({...base,runId:'33333333-3333-4333-8333-333333333333'},now+1000)).error,'limited');await r.start({...base,runId:'33333333-3333-4333-8333-333333333333'},now+3000);assert.equal((await r.totals()).hurdles.count,2);db.raw.run('UPDATE play_count_receipts SET created_at=0');await r.start({...base,runId:'44444444-4444-4444-8444-444444444444'},now+6000);assert.equal((await r.totals()).hurdles.count,3);assert.equal(db.raw.exec('SELECT count(*) FROM play_count_receipts')[0].values[0][0],1);});
test('transaction rollback never leaves receipt without total',async()=>{const{db,r}=await setup();db.raw.run("CREATE TRIGGER deny_counter BEFORE INSERT ON play_count_totals BEGIN SELECT RAISE(ABORT,'test failure');END");await assert.rejects(r.start(base,now));assert.equal(db.raw.exec('SELECT count(*) FROM play_count_receipts')[0].values[0][0],0);});
test('daily global cap uses bounded aggregate rows and admits only one concurrent final slot',async()=>{const{db,r}=await setup(),day=Math.floor(now/86400000);db.raw.run('INSERT INTO play_count_totals VALUES (?,?,?,?,?,?)',['qa','hurdles',9999,now,day,9999]);const results=await Promise.all([r.start(base,now),r.start({...base,deviceId:'33333333-3333-4333-8333-333333333333',runId:'44444444-4444-4444-8444-444444444444'},now)]);assert.equal(results.filter(x=>x.accepted).length,1);assert.equal(results.filter(x=>x.error==='limited').length,1);assert.equal((await r.totals()).hurdles.count,10000);await r.start({...base,runId:'55555555-5555-4555-8555-555555555555'},now+86400000);assert.equal((await r.totals()).hurdles.count,10001);});
test('device daily cap and bounded indexed cleanup limit storage and read work',async()=>{const{db,r}=await setup();await r.start(base,now);const dev=db.raw.exec('SELECT device FROM play_count_receipts')[0].values[0][0],day=Math.floor(now/86400000);db.raw.run('BEGIN');for(let i=0;i<99;i++)db.raw.run('INSERT INTO play_count_receipts VALUES (?,?,?,?,?,?,?)',['qa','seed'+i,'p',dev,'hurdles',now-3000,day]);for(let i=0;i<150;i++)db.raw.run('INSERT INTO play_count_receipts VALUES (?,?,?,?,?,?,?)',['qa','old'+i,'p','other','hurdles',0,0]);db.raw.run('COMMIT');assert.equal((await r.start({...base,runId:'33333333-3333-4333-8333-333333333333'},now+3000)).error,'limited');assert.equal(db.raw.exec('SELECT count(*) FROM play_count_receipts WHERE created_at=0')[0].values[0][0],50);for(const [sql,args,index]of[['SELECT count(*) FROM play_count_receipts WHERE scope=? AND day=? AND device=?',['qa',day,dev],'play_count_daily'],['SELECT 1 FROM play_count_receipts WHERE scope=? AND device=? AND created_at>?',['qa',dev,now-2000],'play_count_device'],['SELECT rowid FROM play_count_receipts WHERE scope=? AND created_at<? LIMIT 100',['qa',1],'play_count_expiry']]){const q=db.raw.prepare('EXPLAIN QUERY PLAN '+sql);q.bind(args);let details='';while(q.step())details+=q.getAsObject().detail;q.free();assert.match(details,new RegExp(index));}assert.equal((await r.totals()).hurdles.count,1);});
test('duplicate accepted before cap stays accepted and conflicting race never counts twice',async()=>{const{db,r}=await setup();const result=await Promise.all([r.start(base,now),r.start({...base,game:'long-jump'},now)]);assert.equal(result.filter(x=>x.accepted).length,1);assert.equal(result.filter(x=>x.error==='conflict').length,1);const winner=(await r.totals()).hurdles.count?base:{...base,game:'long-jump'};db.raw.run('UPDATE play_count_totals SET day_total=10000');assert.deepEqual(await r.start(winner,now+3000),{accepted:true,duplicate:true});assert.equal(Object.values(await r.totals()).reduce((a,x)=>a+x.count,0),1);});

