import {catalog} from '../src/catalog.mjs';
import {renderPage} from '../src/render.mjs';
import {validateSubmission,BOARDS} from '../worker/leaderboard/index.mjs';
const read=p=>readFileSync(new URL('../'+p,import.meta.url),'utf8');
const valid={game:'reaction-rod',rules:'catch-rating-v1',unit:'catches',status:'done',score:5,secondaryScore:4.8123456789,nickname:'島民',deviceId:'00000000-0000-4000-8000-000000000001',submissionId:'00000000-0000-4000-8000-000000000002'};
test('main navigation and independent shelf retain Rod and Fast Hands alongside approved additions',()=>{
 const d=new JSDOM(renderPage(catalog)).window.document;
 assert.deepEqual([...d.querySelectorAll('.site-header nav a')].map(a=>a.textContent),['十項全能','小遊戲','大遊戲','play. one more.','關於']);
 assert.deepEqual(catalog.games.map(g=>g.id),['long-jump', 'hurdles', 'high-jump', 'pole-vault', 'shot-put', 'discus', 'sprint-100m', 'run-400m', 'run-1500m', 'javelin']);
 assert.deepEqual(catalog.minigames.map(g=>g.id),['overtime-pinball','courtesy-contest', 'fast-hands', 'fast-hands-catch', 'fast-hands-duel', 'beer-slide', 'reaction-rod', 'tower-climb']);
 assert.equal(d.querySelectorAll('#minigames .game-card').length,8);
 assert.deepEqual([...d.querySelectorAll('[data-play-count]')].map(n=>n.dataset.playCount),['long-jump', 'hurdles', 'high-jump', 'pole-vault', 'shot-put', 'discus', 'sprint-100m', 'run-400m', 'run-1500m', 'javelin', 'overtime-pinball', 'courtesy-contest', 'fast-hands', 'fast-hands-catch', 'fast-hands-duel', 'beer-slide', 'reaction-rod', 'tower-climb', 'taiwankart', 'taiwanfighter', 'soul10power', 'arcadeplatform']);
 assert.equal(d.querySelector('#minigames .game-cta[href="/games/reaction-rod/"]').getAttribute('href'),'/games/reaction-rod/');
 assert.equal(d.querySelector('[data-external-id="taiwanfighter"] a').getAttribute('href'),'/api/play-counts/entries/taiwanfighter');
});
test('Rod API validates full precision without weakening legacy schemas or admitting other games',()=>{
 assert.ok(BOARDS['reaction-rod']); assert.deepEqual(validateSubmission(valid),valid);
 for(const v of [0,11,1.2,NaN])assert.throws(()=>validateSubmission({...valid,score:v}));
 for(const v of [-1,11,NaN,Infinity,'5',undefined])assert.throws(()=>validateSubmission({...valid,secondaryScore:v}));
 for(const game of ['sprint-100m','javelin','high-jump','shot-put','beer-slide'])assert.throws(()=>validateSubmission({...valid,game}));
 const {secondaryScore,...legacy}=valid;
 assert.throws(()=>validateSubmission({...legacy,game:'long-jump',rules:'journey-km-v1',unit:'km',status:'valid',secondaryScore:0}));
});
test('Rod imports only local adapters while all visible routes and licensed audio exist',()=>{
 assert.ok(existsSync(new URL('../public/games/reaction-rod/index.html',import.meta.url)));
 const g=read('public/games/reaction-rod/game.mjs');
 for(const file of ['leaderboard.mjs','play-counts.mjs','audio.mjs','game-audio-events.mjs'])assert.ok(g.includes("'./"+file+"'"));
 assert.doesNotMatch(g,/beer-slide/);
 assert.match(read('public/games/reaction-rod/index.html'),/src="\.\/layout\.mjs"/);
 assert.doesNotMatch(read('public/games/reaction-rod/index.html'),/\.\.\/beer-slide/);
});

// Native navigation covers touch, Enter, modifier/middle clicks and browser
// "open in new tab" without duplicate click/keydown/pointer telemetry.
export const fighterEntryPath='/api/play-counts/entries/taiwanfighter';
export const entryDestinations=Object.freeze({taiwanfighter:'https://taiwanfighter.playformosa.workers.dev/',taiwankart:'https://taiwankart.playformosa.workers.dev/',soul10power:'https://soul10power.vercel.app/',arcadeplatform:'https://arcadeplatform.playformosa.workers.dev/'});
export const entryKey=path=>{const key=path.startsWith('/api/play-counts/entries/')?path.slice('/api/play-counts/entries/'.length):'';return Object.hasOwn(entryDestinations,key)?key:null;};

function isEntryNavigation(request,url){
 if(request.method!=='GET'||url.search)return false;
 if(/prefetch|prerender/i.test((request.headers.get('Purpose')||'')+' '+(request.headers.get('Sec-Purpose')||'')))return false;
 for(const [name,expected] of [['Sec-Fetch-Mode','navigate'],['Sec-Fetch-Dest','document']]){
  const value=request.headers.get(name);if(value!==null&&value!==expected)return false;
 }
 // Browser UI (for example, opening a link via a context menu) may report none.
 const site=request.headers.get('Sec-Fetch-Site');
 if(site!==null&&!['same-origin','none'].includes(site))return false;
 return true;
}

async function countEntry(env,now,key){
 // Entry counts have no per-device cooldown. They do not consume the existing
 // gameplay daily quota and require only one bounded aggregate row per scope.
 const day=Math.floor(now/86400000);
 await env.DB.batch([env.DB.prepare(`INSERT INTO play_count_totals(scope,counter_key,total,since,day,day_total)
 VALUES (?,?,1,?,?,0)
 ON CONFLICT(scope,counter_key) DO UPDATE SET total=play_count_totals.total+1,day=excluded.day`)
 .bind(env.LEADERBOARD_SCOPE,key,now,day)]);
}

export function handleFighterEntry(request,env,now,context){return handleExternalEntry(request,env,now,context);}
export function handleExternalEntry(request,env,now,context){
 const key=entryKey(new URL(request.url).pathname);if(!key)return new Response(null,{status:404});
 const destination=entryDestinations[key];
 if(!['GET','HEAD'].includes(request.method))return new Response(null,{status:405,headers:{Allow:'GET, HEAD','Cache-Control':'no-store'}});
 const url=new URL(request.url);
 if(env.PLAY_COUNTS_ENABLED==='true'&&['qa','production'].includes(env.LEADERBOARD_SCOPE)&&env.DB&&env.LEADERBOARD_ORIGIN===url.origin&&isEntryNavigation(request,url)){
  const work=countEntry(env,now,key).catch(()=>{}); // Best effort: D1 failure cannot prevent entering the game.
  context?.waitUntil(work);
 }
 return new Response(null,{status:302,headers:{Location:destination,'Cache-Control':'no-store','Referrer-Policy':'no-referrer','X-Robots-Tag':'noindex, nofollow'}});
}

const digest=async text=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)))].map(x=>x.toString(16).padStart(2,'0')).join('');
export class PlayCountsRepository{
 constructor(db,scope){this.db=db;this.scope=scope;}
 async totals(){const keys=['long-jump','hurdles','high-jump','pole-vault','shot-put','discus','sprint-100m','run-400m','run-1500m','javelin','reaction-rod','beer-slide','tower-climb','fast-hands','fast-hands-catch','fast-hands-duel','courtesy-contest',...(this.scope==='production'?['overtime-pinball']:[]),'taiwanfighter','taiwankart','soul10power','arcadeplatform','home'];const rows=await this.db.prepare(`SELECT counter_key,total,since FROM play_count_totals WHERE scope=? AND counter_key IN (${keys.map(()=>'?').join(',')})`).bind(this.scope,...keys).all();const out=Object.fromEntries(keys.map(k=>[k,{count:0,since:null}]));for(const r of rows.results)out[r.counter_key]={count:r.total,since:r.since};return out;}
 async start(data,now){const device=await digest(this.scope+':'+data.deviceId),payload=await digest(JSON.stringify([data.game,data.deviceId,data.runId,data.startedAt])),day=Math.floor(now/86400000),p=(q,...args)=>this.db.prepare(q).bind(...args);
 const home=data.game==='home',windowMs=home?1800000:2000;
 const rows=await this.db.batch([
 p('SELECT payload FROM play_count_receipts WHERE scope=? AND id=?',this.scope,data.runId),
 p(`DELETE FROM play_count_receipts WHERE rowid IN (SELECT rowid FROM play_count_receipts WHERE scope=? AND created_at<?${data.game==='overtime-pinball'?' AND counter_key=?':''} LIMIT 100)`,this.scope,now-7*86400000,...(data.game==='overtime-pinball'?[data.game]:[])),
 p(`INSERT OR IGNORE INTO play_count_receipts(scope,id,payload,device,counter_key,created_at,day)
 SELECT ?,?,?,?,?,?,? WHERE NOT EXISTS(SELECT 1 FROM play_count_receipts WHERE scope=? AND device=? AND created_at>? AND ${home?"counter_key='home'":"counter_key!='home'"})
 AND (SELECT count(*) FROM play_count_receipts WHERE scope=? AND day=? AND device=?)<100
 AND (SELECT COALESCE(SUM(day_total),0) FROM play_count_totals WHERE scope=? AND day=?)<10000`,this.scope,data.runId,payload,device,data.game,now,day,this.scope,device,now-windowMs,this.scope,day,device,this.scope,day),
 // Immediately follows receipt INSERT: changes() belongs to that INSERT, never cleanup.
 p(`INSERT INTO play_count_totals(scope,counter_key,total,since,day,day_total) SELECT ?,?,1,?,?,1 WHERE changes()=1
 ON CONFLICT(scope,counter_key) DO UPDATE SET total=play_count_totals.total+1,day=excluded.day,day_total=CASE WHEN play_count_totals.day=excluded.day THEN play_count_totals.day_total+1 ELSE 1 END`,this.scope,data.game,now,day),
 p('SELECT payload FROM play_count_receipts WHERE scope=? AND id=?',this.scope,data.runId),
 ...(home?[p("SELECT created_at FROM play_count_receipts WHERE scope=? AND device=? AND created_at>? AND counter_key='home' ORDER BY created_at DESC LIMIT 1",this.scope,device,now-1800000)]:[])]);
 const receipt=rows[4].results[0],lastHome=rows[5]?.results[0]?.created_at,nextEligibleAt=lastHome==null?null:lastHome+1800000;if(!receipt){if(home&&nextEligibleAt>now)return{accepted:true,counted:false,nextEligibleAt};return{error:'limited'}};if(receipt.payload!==payload)return{error:'conflict'};return{accepted:true,duplicate:rows[0].results.length>0,...(home?{counted:rows[0].results.length===0,nextEligibleAt}:{})};
 }
}
